import type { Metadata } from "next";
import { siteConfig } from "@/config/siteConfig";

/*
 * One place for page metadata. Next merges metadata *shallowly*: a page that sets `openGraph`
 * replaces the layout's whole `openGraph`. So every page builds the full set here — canonical URL,
 * Open Graph and Twitter card — instead of relying on inheritance.
 */

/** Default share image (generated by src/app/og-image/route.tsx). */
export const DEFAULT_OG_IMAGE = {
  url: "/og-image",
  width: 1200,
  height: 630,
  alt: `${siteConfig.name} — ${siteConfig.tagline}`,
};

/** "/products/x" → "https://shreeni-collection.in/products/x" */
export const absoluteUrl = (path: string) => new URL(path, siteConfig.url).toString();

type PageSeo = {
  /** Page title without the brand; the layout template adds " | Shreeni Sarees". Omit for the home page. */
  title?: string;
  description: string;
  /** Canonical path, e.g. "/about/story". */
  path: string;
  /** Share images (absolute or root-relative). Defaults to the brand image. */
  images?: string[];
  /** Keep the page out of search results (thin, private or placeholder content). */
  noIndex?: boolean;
};

export function pageMetadata({ title, description, path, images, noIndex }: PageSeo): Metadata {
  const fullTitle = title ? siteConfig.seo.titleTemplate.replace("%s", title) : siteConfig.seo.defaultTitle;
  const ogImages = images?.length ? images.map((url) => ({ url, alt: title ?? siteConfig.name })) : [DEFAULT_OG_IMAGE];
  return {
    ...(title && { title }),
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      url: path,
      siteName: siteConfig.name,
      locale: siteConfig.locale,
      title: fullTitle,
      description,
      images: ogImages,
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: ogImages.map((i) => i.url),
    },
    ...(noIndex && { robots: { index: false, follow: true } }),
  };
}

/** Trim long text to a search-snippet-sized description (~155 chars, on a word boundary). */
export function snippet(text: string, max = 155): string {
  const clean = text.replace(/\s+/g, " ").trim();
  if (clean.length <= max) return clean;
  const cut = clean.slice(0, max);
  return `${cut.slice(0, cut.lastIndexOf(" ")).replace(/[,.;:\s]+$/, "")}…`;
}
